from lib import *
chapter(7,'science','the-world-of-metals-and-non-metals','The World of Metals and Non-metals',
 ('Gold ring and coal','A gold ring shines and can be beaten into thin sheets. Coal is dull and crumbles. Elements can be sorted by their properties into metals and non-metals.'),
 [('Properties of metals',['Metals are generally hard, shiny and strong. They are good conductors of heat and electricity.','Malleable means they can be beaten into thin sheets, like aluminium foil. Ductile means they can be drawn into wires, like copper.','Metals make a ringing sound when struck. This is called sonorous.']),
  ('Non-metals',['Non-metals are usually dull, brittle and poor conductors, such as carbon, sulphur and oxygen.','Some are gases, such as oxygen and nitrogen. Mercury is a liquid metal.','Graphite is a form of carbon that conducts electricity, an exception.']),
  ('Reactions',['Metals react with oxygen to make metal oxides. Iron rusts in damp air.','Metals react with acids to give hydrogen gas.','Non-metal oxides, such as carbon dioxide, make acidic solutions in water.']),
  ('Uses',['Copper is used in wires, iron in tools, aluminium in foil and gold in jewellery. Sulphur is used in matches and fireworks.'])],
 [('Why are electrical wires made of copper?',[('Copper conducts electricity well.','Good conductor.'),('It is also ductile and can be drawn into wires.','Ductility.')])],
 ('Explain how you would test if a material is a metal.',['Check shine, hardness, sound and conduction.'],['Thinking all metals are solid; mercury is liquid.']),
 ['Metals are shiny, malleable, ductile and conduct.','Non-metals are brittle and poor conductors.','Metals rust or react with acids.'],
 [mcq('1',1,'A property that lets metals be drawn into wires is','ductility',[('malleability','That is beating into sheets.'),('sonority','That is ringing sound.')],'Ductile.'),
  mcq('2',1,'Which is a non-metal?','Sulphur',[('Copper','Copper is a metal.'),('Iron','Iron is a metal.')],'It is dull and brittle.'),
  tf('3',1,'Mercury is a liquid metal.',True,'It is the only common metal that is liquid at room temperature.'),
  mcq('4',1,'Metals ring when struck. This is called','sonorous',[('brittle','Brittle breaks easily.'),('dull','Metals are shiny.')],'Bells are made of metals.'),
  mcq('5',2,'Rusting needs','air and moisture',[('only light','Light is not required.'),('only cold','Temperature alone does not cause rust.')],'Iron plus oxygen and water.'),
  mcq('6',2,'Metals react with acids to give','hydrogen gas',[('oxygen','It is hydrogen.'),('carbon dioxide','That comes from carbonates.')],'Bubbles of hydrogen.'),
  tf('7',2,'Graphite conducts electricity.',True,'It is a non-metal exception.'),
  mcq('8',3,'Aluminium foil shows that aluminium is','malleable',[('ductile','Ductile means drawn into wire.'),('brittle','Brittle breaks.')],'It can be beaten into thin sheets.')],
 keep=['metal','malleable','ductile'])
chapter(7,'science','changes-around-us-physical-and-chemical','Changes Around Us: Physical and Chemical',
 ('Ice and the burnt toast','Ice melts into water and can freeze again. Bread burnt into toast cannot become bread again. Some changes can be reversed and some cannot.'),
 [('Physical changes',['In a physical change no new substance is formed. Melting ice, dissolving sugar, cutting paper and stretching a rubber band are physical changes.','Many physical changes can be reversed.']),
  ('Chemical changes',['In a chemical change a new substance is formed with different properties. Burning wood, rusting iron, cooking food and souring milk are chemical changes.','Signs include a change in colour, gas bubbles, heat or light, or a new smell.','Chemical changes are usually permanent.']),
  ('Rusting and burning',['Rusting needs iron, air and water. We prevent it by painting, oiling or galvanising.','Burning needs a fuel and oxygen. A fire is put out by removing one of these.']),
  ('Crystallisation',['Crystals of salt or copper sulphate can be made by evaporating a saturated solution slowly. This is a physical change.']),
  ('Desirable and slow changes',['Some changes help us, like cooking. Some harm us, like rusting. Some are slow, like ripening, and some are quick, like burning a match.'])],
 [('Is cooking an egg a physical or chemical change?',[('A new substance with different properties forms.','Look for new substances.'),('It is a chemical change and cannot be reversed.','Conclusion.')])],
 ('How can you tell if a change is chemical?',['A new substance forms.','Often with gas, heat, colour or smell.'],['Thinking all reversible changes are physical or all irreversible changes are chemical.']),
 ['Physical change: no new substance.','Chemical change: new substance.','Rusting needs air and water.','Burning needs fuel and oxygen.'],
 [mcq('1',1,'Melting ice is a','physical change',[('chemical change','Water stays water.'),('permanent change','It can freeze again.')],'No new substance.'),
  mcq('2',1,'Burning paper is a','chemical change',[('physical change','New substances like ash and smoke form.'),('reversible change','You cannot get paper back.')],'New substances form.'),
  tf('3',1,'Rusting is a chemical change.',True,'Iron oxide is a new substance.'),
  mcq('4',1,'A sign of chemical change is','gas bubbles',[('change of shape','That is physical.'),('dissolving','That is physical.')],'New gas forms.'),
  mcq('5',2,'Rusting can be prevented by','painting',[('wetting','Water speeds rust.'),('heating','It does not prevent rust.')],'Keeps air and water away.'),
  mcq('6',2,'Cooking rice is a','chemical change',[('physical change','The rice changes permanently.'),('slow change','It is quick.')],'New properties.'),
  tf('7',2,'Dissolving sugar in water is a chemical change.',False,'The sugar can be recovered by evaporation.'),
  mcq('8',3,'To put out a fire you can','cut off oxygen',[('add fuel','This would feed it.'),('add heat','It would burn more.')],'Remove fuel, oxygen or heat.')],
 keep=['physical change','chemical change','rusting'])
chapter(7,'science','adolescence-a-stage-of-growth-and-change','Adolescence: A Stage of Growth and Change',
 ('Growing up','Rani notices that she is taller, her voice and moods are changing and she wants more privacy. These changes are a normal part of growing up called adolescence.'),
 [('Changes during adolescence',['Adolescence is the stage from about 10 to 19 years when a child grows into an adult.','Both boys and girls grow taller and gain weight. Boys\' voices deepen and facial hair appears. Girls begin menstruation.','These changes happen at different times for different people and are completely normal.']),
  ('Hormones',['Hormones are chemicals made by glands that control the changes of the body.','The pituitary gland in the brain controls other glands.']),
  ('Health and hygiene',['Eat a balanced diet with enough iron and calcium, sleep well, exercise and keep the body clean.','Bathe daily, wash hair, change clothes and care for teeth. During menstruation, use clean pads or cloth and change them often.']),
  ('Emotions and behaviour',['Mood swings, anger and worry are common in adolescence. Talking to parents, teachers or a trusted adult helps.','Choose friends wisely and avoid harmful habits such as tobacco.'])],
 [('Why should adolescents eat iron-rich food?',[('Their bodies are growing fast.','Growth need.'),('Iron helps make blood.','Prevents weakness.')])],
 ('What advice would you give a friend who feels moody and anxious?',['It is normal.','Talk to a trusted adult.','Keep healthy habits.'],['Hiding worries.','Following unhealthy habits because friends do.']),
 ['Adolescence is a stage of growth from about 10 to 19.','Hormones control body changes.','Hygiene and good food are needed.','Talking about emotions helps.'],
 [mcq('1',1,'Adolescence starts at about','10 years',[('5 years','Too early.'),('25 years','Too late.')],'Between 10 and 19.'),
  tf('2',1,'Changes in adolescence happen at the same age for everyone.',False,'Everyone grows at their own pace.'),
  mcq('3',1,'Hormones are made by','glands',[('bones','Bones do not make hormones.'),('nails','Nails do not.')],'Chemical messengers.'),
  mcq('4',1,'A change in boys is','deepening of voice',[('menstruation','That occurs in girls.'),('loss of hair','Not a normal sign.')],'Adolescent boys\' voices deepen.'),
  mcq('5',2,'Which helps keep adolescents healthy?','Balanced diet and exercise',[('Junk food only','It lacks nutrients.'),('Skipping sleep','Sleep is needed for growth.')],'Healthy habits.'),
  tf('6',2,'Mood swings are common in adolescence.',True,'Hormone changes affect feelings.'),
  mcq('7',2,'The gland that controls other glands is the','pituitary',[('thyroid','It controls metabolism.'),('adrenal','It produces adrenaline.')],'It is in the brain.'),
  mcq('8',3,'If you feel worried you should','talk to a trusted adult',[('hide it','This makes it worse.'),('get angry','Not helpful.')],'Support helps.')],
 keep=['adolescence','hormone'])
